    const hs = ls.map((l) => $('#b' + l.dataset.k));
    let k = 0;
    hs.forEach((h, i) => {
      if (h && h.offsetTop - bd.scrollTop < 90) k = i;
    });
    if (bd.scrollTop + bd.clientHeight >= bd.scrollHeight - 4) k = hs.length - 1;
    ls.forEach((l, i) => l.classList.toggle('on', i === k));
