    bv.innerHTML = `<div class="crumbs"><button class="back" id="back" aria-label="返回"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M15 18l-6-6 6-6"/></svg></button><span class="cf" id="cf">${gf(s.c, s.sym, { tiny: true })}</span><span class="seg ${openDir ? '' : 'cur'}">${esc(s.label)}</span>${openDir ? openDir.split('/').map((p, i, a) => `<span class="seg">/</span><span class="seg ${i === a.length - 1 ? 'cur' : ''}">${esc(p)}</span>`).join('') : ''}<span class="sp"></span><div class="sizes" id="sizes">${['s', 'm', 'l'].map((z) => `<button data-z="${z}" class="${size === z ? 'on' : ''}" title="${z === 's' ? '小 ⌘−' : z === 'l' ? '大 ⌘+' : '中'}">${z.toUpperCase()}</button>`).join('')}</div></div>
    <div class="desk"><div class="tree" id="tree"><div class="tnode ${openDir ? '' : 'on'}" data-p=""><span style="width:12px;flex:none"></span>${gf(s.c, s.sym, { tiny: true, sheets: 1 })}<span class="nm">全部</span><span class="ct">${count(troot)}</span></div>${th(troot, '')}</div>
    <div class="grid ${size}" id="grid">${docs.map((d) => docCard(d)).join('')}${all.length > GRID_MAX ? `<div class="more">还有 ${all.length - GRID_MAX} 篇，在左边目录里点进子文件夹看</div>` : ''}${all.length ? '' : '<div class="more">这里还没有文档</div>'}</div></div>`;
