      $$('#grid .doc')
        .slice(0, 24)
        .forEach((c, i) => {
          const r = c.getBoundingClientRect();
          const rot = (i % 2 ? 1 : -1) * (2 + ((i * 7) % 4));
          settle(anim(c, [{ transform: `translate(${cx - (r.left + r.width / 2)}px,${cy - (r.top + r.height / 2)}px) scale(.16) rotate(${rot * 2}deg)`, opacity: 0 }, { opacity: 1, offset: 0.25 }, { transform: `rotate(${rot * 0.2}deg)`, offset: 0.84 }, { transform: 'none', opacity: 1 }], { duration: 580, delay: 80 + i * 42, easing: 'cubic-bezier(.25,.8,.3,1)' }));
        });
