      anim(c, [{ transform: 'none', opacity: 1 }, { transform: `translate(${cx - (r.left + r.width / 2)}px,${cy - (r.top + r.height / 2)}px) scale(.1) rotate(${(i % 2 ? 1 : -1) * 8}deg)`, opacity: 0 }], { duration: 380, delay: i * 20, easing: 'cubic-bezier(.5,0,.75,.3)' });
