      old = small.textContent;
    small.textContent = '在弹出的窗口里选一个文件夹…';
    let picked;
    try {
      picked = await post('pick-folder');
    } catch (e) {
      picked = { error: e.message };
    }
    if (disposed) return;
    btn.classList.remove('wait');
    small.textContent = old;
    if (picked.error) {
      toast('打不开选择窗口：' + picked.error);
      return;
    }
    if (picked.cancelled || !picked.path) return;
    let r;
    try {
      r = await post('sources', { action: 'add', path: picked.path });
    } catch (e) {
      toast('加不进来：' + e.message);
      return;
    }
    await pollStatus(true);
    renderSources();
    renderChatScope();
    const row = $(`.srow[data-id="${CSS.escape(r.source.id)}"]`, srv);
