    row.scrollIntoView({ block: 'nearest' });
    // 放到桌上：从上方落下，触底轻弹
    settle(anim(row, [{ transform: 'translateY(-56px)', opacity: 0 }, { transform: 'translateY(4px)', opacity: 1, offset: 0.7 }, { transform: 'none', opacity: 1 }], { duration: 540, easing: 'cubic-bezier(.4,0,.6,1)' }));
