    for (const n of ans.querySelectorAll('p,li')) n.normalize();
    if (tu.stopped) ans.insertAdjacentHTML('beforeend', '<span class="stopped">已停止</span>');
    if (tu.error) ans.insertAdjacentHTML('beforeend', `<span class="err">${esc(tu.error)}</span>`);
